"""
Generate IAA (Inter-Annotator Agreement) report from Label Studio JSON export.
"""

import json
import math
from collections import defaultdict
from typing import Dict, List, Tuple, Set
from datetime import datetime
from itertools import combinations


def load_json(filepath: str) -> List[Dict]:
    """Load JSON data from Label Studio export."""
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)


def extract_annotations(data: List[Dict]) -> Dict[int, Dict]:
    """
    Extract annotations organized by record ID.
    Returns: {record_id: {"question": str, "annotators": {email: scores_dict}}}
    """
    records = defaultdict(lambda: {"question": "", "annotators": {}})

    for task in data:
        task_id = task['id']
        question = task.get('data', {}).get('question', '')

        for annotation in task.get('annotations', []):
            annotator_email = annotation.get('completed_by', {}).get('email', 'Unknown')
            annotator_id = annotation.get('completed_by', {}).get('id')

            scores = {}
            is_reviewed = False

            for result in annotation.get('result', []):
                from_name = result.get('from_name', '')
                value = result.get('value', {}).get('choices', [''])[0]

                # Extract metric scores
                if from_name.startswith('score_'):
                    metric = from_name.replace('score_', '')
                    try:
                        scores[metric] = int(value) if value else None
                    except ValueError:
                        scores[metric] = None

                # Check if reviewed
                if from_name == 'not-sensible' and value == 'reviewed':
                    is_reviewed = True

            records[task_id]['question'] = question
            records[task_id]['annotators'][annotator_email] = {
                'scores': scores,
                'reviewed': is_reviewed,
                'annotator_id': annotator_id
            }

    return dict(records)


def quadratic_weighted_kappa(scores1: List[int], scores2: List[int], max_rating: int = 2) -> float:
    """
    Calculate Quadratic Weighted Kappa (QWK) for two annotators.
    """
    if len(scores1) != len(scores2):
        return 0.0

    if not scores1 or all(s is None for s in scores1):
        return 0.0

    # Filter out None values
    valid_pairs = [(s1, s2) for s1, s2 in zip(scores1, scores2) 
                   if s1 is not None and s2 is not None]

    if not valid_pairs:
        return 0.0

    scores1 = [s1 for s1, s2 in valid_pairs]
    scores2 = [s2 for s1, s2 in valid_pairs]

    n = len(scores1)

    # Create confusion matrix
    matrix = [[0 for _ in range(max_rating + 1)] for _ in range(max_rating + 1)]
    for s1, s2 in zip(scores1, scores2):
        matrix[int(s1)][int(s2)] += 1

    # Calculate observed agreement
    po = sum(matrix[i][i] for i in range(max_rating + 1)) / n if n > 0 else 0

    # Calculate expected agreement
    row_marginals = [sum(row) / n for row in matrix]
    col_marginals = [sum(matrix[i][j] for i in range(max_rating + 1)) / n 
                     for j in range(max_rating + 1)]

    pe = 0
    for i in range(max_rating + 1):
        for j in range(max_rating + 1):
            weight = ((i - j) ** 2) / (max_rating ** 2)
            pe += weight * row_marginals[i] * col_marginals[j]

    # Calculate kappa
    kappa = (po - pe) / (1 - pe) if pe < 1 else 0.0

    return round(kappa, 3)


def calculate_iaa_metrics(records: Dict[int, Dict]) -> Dict:
    """Calculate IAA metrics across all records."""

    # Get all unique annotators
    all_annotators = set()
    for record in records.values():
        all_annotators.update(record['annotators'].keys())

    all_annotators = sorted(list(all_annotators))

    # Map emails to names (from existing data pattern)
    email_to_name = {
        'nitzan.gour@gmail.com': 'Nitzan',
        'daniellehuy@gmail.com': 'Danielle',
        'atar.bitan@gmail.com': 'Atar',
        'noga.levy92@gmail.com': 'Noga',
    }

    annotator_names = [email_to_name.get(email, email.split('@')[0].title()) 
                       for email in all_annotators]

    # Calculate QWK for each metric and annotator pair
    metrics = ['coherence', 'relevance', 'completeness', 'faithfulness']
    qwk_by_metric = {metric: {} for metric in metrics}

    for pair in combinations(range(len(all_annotators)), 2):
        idx1, idx2 = pair
        email1, email2 = all_annotators[idx1], all_annotators[idx2]
        name1, name2 = annotator_names[idx1], annotator_names[idx2]

        for metric in metrics:
            scores1 = []
            scores2 = []

            for record in records.values():
                ann1_data = record['annotators'].get(email1, {}).get('scores', {}).get(metric)
                ann2_data = record['annotators'].get(email2, {}).get('scores', {}).get(metric)

                if ann1_data is not None and ann2_data is not None:
                    scores1.append(ann1_data)
                    scores2.append(ann2_data)

            kappa = quadratic_weighted_kappa(scores1, scores2)
            qwk_by_metric[metric][f"{name1}-{name2}"] = kappa

    # Calculate overall QWK by metric
    overall_qwk = {}
    for metric in metrics:
        if qwk_by_metric[metric]:
            avg_qwk = sum(qwk_by_metric[metric].values()) / len(qwk_by_metric[metric])
            overall_qwk[metric] = round(avg_qwk, 4)

    # Calculate agreement/disagreement
    total_records = len(records)
    disagreement_counts = defaultdict(int)
    records_with_disagreement = set()

    for record_id, record in records.items():
        annotators = record['annotators']
        if len(annotators) < 2:
            continue

        ann_list = list(annotators.items())
        for i in range(len(ann_list)):
            for j in range(i + 1, len(ann_list)):
                email1, data1 = ann_list[i]
                email2, data2 = ann_list[j]
                scores1 = data1['scores']
                scores2 = data2['scores']

                for metric in metrics:
                    s1 = scores1.get(metric)
                    s2 = scores2.get(metric)
                    if s1 is not None and s2 is not None and s1 != s2:
                        disagreement_counts[metric] += 1
                        records_with_disagreement.add(record_id)

    disagreement_rate = len(records_with_disagreement) / total_records * 100 if total_records > 0 else 0

    # Review coverage
    review_coverage = {name: {'reviewed': 0, 'not_reviewed': 0} for name in annotator_names}
    for record in records.values():
        for email, ann_data in record['annotators'].items():
            name = email_to_name.get(email, email.split('@')[0].title())
            if name in review_coverage:
                if ann_data.get('reviewed', False):
                    review_coverage[name]['reviewed'] += 1
                else:
                    review_coverage[name]['not_reviewed'] += 1

    return {
        'all_annotators': all_annotators,
        'annotator_names': annotator_names,
        'total_records': total_records,
        'disagreement_count': len(records_with_disagreement),
        'agreement_count': total_records - len(records_with_disagreement),
        'disagreement_rate': round(disagreement_rate, 1),
        'qwk_by_metric': qwk_by_metric,
        'overall_qwk': overall_qwk,
        'review_coverage': review_coverage,
        'email_to_name': email_to_name,
        'records': records
    }


def get_per_metric_insights(qwk_by_metric: Dict) -> Dict:
    """Extract min/max QWK for each metric."""
    insights = {}

    for metric, pairs in qwk_by_metric.items():
        if pairs:
            min_pair = min(pairs.items(), key=lambda x: x[1])
            max_pair = max(pairs.items(), key=lambda x: x[1])
            gap = max_pair[1] - min_pair[1]

            insights[metric] = {
                'worst_pair': min_pair[0],
                'worst_qwk': min_pair[1],
                'best_pair': max_pair[0],
                'best_qwk': max_pair[1],
                'gap': round(gap, 3)
            }

    return insights


def get_heatmap_data(qwk_by_metric: Dict, annotator_names: List[str]) -> Dict:
    """Create heatmap data organized by metric and annotator pairs."""
    heatmap_data = {}

    for metric, pairs in qwk_by_metric.items():
        # Create matrix
        n = len(annotator_names)
        matrix = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]

        for pair_name, qwk in pairs.items():
            names = pair_name.split('-')
            if names[0] in annotator_names and names[1] in annotator_names:
                i = annotator_names.index(names[0])
                j = annotator_names.index(names[1])
                matrix[i][j] = qwk
                matrix[j][i] = qwk

        heatmap_data[metric] = matrix

    return heatmap_data


def get_color_for_value(value: float, max_val: float = 1.0) -> str:
    """Get RGB color for heatmap value (green for high agreement, red for low)."""
    # Normalize to 0-1 range
    normalized = (value + 1) / 2 if value < 0 else value / max_val
    normalized = max(0, min(1, normalized))

    # Green (high) to Red (low)
    if normalized > 0.5:
        # Green range
        r = int(212 + (1 - normalized) * 43)
        g = 237
        b = 218
    else:
        # Red range
        r = 245
        g = int(216 + normalized * 11)
        b = 218

    return f"rgb({r},{g},{b})"


def find_top_disagreement_records(records: Dict[int, Dict], iaa_metrics: Dict, limit: int = 40) -> List[Dict]:
    """Find records with most disagreement across metrics."""
    email_to_name = iaa_metrics['email_to_name']
    metrics = ['coherence', 'relevance', 'completeness', 'faithfulness']

    record_disagreements = []

    for record_id, record in records.items():
        disagreement_count = 0
        disagreement_details = defaultdict(list)

        annotators = record['annotators']
        ann_list = list(annotators.items())

        for i in range(len(ann_list)):
            for j in range(i + 1, len(ann_list)):
                email1, data1 = ann_list[i]
                email2, data2 = ann_list[j]

                for metric in metrics:
                    s1 = data1['scores'].get(metric)
                    s2 = data2['scores'].get(metric)

                    if s1 is not None and s2 is not None:
                        if s1 != s2:
                            disagreement_count += 1
                            disagreement_details[metric].append({
                                'ann1': (email_to_name.get(email1, email1), s1),
                                'ann2': (email_to_name.get(email2, email2), s2),
                            })

        if disagreement_count > 0:
            # Build score details string
            score_details = []
            for metric in metrics:
                scores_str = ", ".join([
                    f"{email_to_name.get(email, email)}={data['scores'].get(metric, '?')}"
                    for email, data in annotators.items()
                    if data['scores'].get(metric) is not None
                ])
                if scores_str:
                    score_details.append(f"{metric.title()}: {scores_str}")

            record_disagreements.append({
                'id': f"{record_id:08x}",
                'numeric_id': record_id,
                'question': record['question'],
                'disagreement_count': disagreement_count,
                'metrics': ', '.join([m.title() for m in metrics if disagreement_details.get(m)]),
                'score_details': ' | '.join(score_details)
            })

    # Sort by disagreement count (descending)
    record_disagreements.sort(key=lambda x: x['disagreement_count'], reverse=True)

    return record_disagreements[:limit]


def generate_html(iaa_metrics: Dict, top_disagreements: List[Dict]) -> str:
    """Generate HTML report."""

    insights = get_per_metric_insights(iaa_metrics['qwk_by_metric'])
    heatmap_data = get_heatmap_data(iaa_metrics['qwk_by_metric'], iaa_metrics['annotator_names'])

    overall_qwk = iaa_metrics['overall_qwk']
    qwk_labels = list(overall_qwk.keys())
    qwk_values = list(overall_qwk.values())

    review_coverage = iaa_metrics['review_coverage']
    review_labels = list(review_coverage.keys())
    review_reviewed = [review_coverage[name]['reviewed'] for name in review_labels]
    review_not_reviewed = [review_coverage[name]['not_reviewed'] for name in review_labels]

    total_review_marks = sum(review_reviewed)
    total_possible_marks = len(review_labels) * iaa_metrics['total_records']
    overall_review_completion = (total_review_marks / total_possible_marks * 100) if total_possible_marks > 0 else 0

