                color = get_color_for_value(value)
                row_html += f'<td style="background:{color};">{value:.3f}</td>'
            row_html += "</tr>"
            rows += row_html

        heatmap_cards += f"""
    <div class="heatmap-card">
      <h4>{metric.title()}</h4>
      <table class="heatmap-table">
        <thead><tr>{header_cells}</tr></thead>
