def main(json_filepath: str, output_filepath: str):
    """Main function to generate report."""
    print(f"Loading JSON from {json_filepath}...")
    data = load_json(json_filepath)
    print(f"Loaded {len(data)} records")

    print("Extracting annotations...")
    records = extract_annotations(data)
    print(f"Extracted annotations for {len(records)} unique records")

    print("Calculating IAA metrics...")
    iaa_metrics = calculate_iaa_metrics(records)

    print("Finding top disagreement records...")
    top_disagreements = find_top_disagreement_records(records, iaa_metrics)

    print("Generating HTML report...")
    html = generate_html(iaa_metrics, top_disagreements)

    print(f"Writing HTML to {output_filepath}...")
    with open(output_filepath, 'w', encoding='utf-8') as f:
        f.write(html)

    print(f"\n✓ Report generated successfully!")
    print(f"  Total records: {iaa_metrics['total_records']}")
    print(f"  Disagreement rate: {iaa_metrics['disagreement_rate']}%")
    print(f"  Annotators: {', '.join(iaa_metrics['annotator_names'])}")
    print(f"  Overall QWK: {iaa_metrics['overall_qwk']}")


