        </div>
        <div class="progress-track" aria-label="overall review completion progress">
          <div class="progress-fill" id="overallReviewProgressFill"></div>
        </div>
      </div>
      <canvas id="reviewCoverageChart" height="110"></canvas>
    </div>

    <div class="section">
      <h2>4) Top Disagreement Records</h2>
      <div class="note">Rule used: a metric is marked as disagreement when annotators have non-identical scores. Table shows top 40 records by disagreement count.</div>
      <div class="scroll">
        <table class="data-table">
          <thead>
            <tr>
              <th>record_id</th>
              <th># disagreeing metrics</th>
