      </div>
    </div>

    <div class="footer">Generated: {datetime.now().strftime('%Y-%m-%d %H:%M')}</div>
  </div>

  <script>
    const overallData = {{"labels": {json.dumps(qwk_labels)}, "values": {json.dumps(qwk_values)}}};
    const reviewData = {{"labels": {json.dumps(review_labels)}, "reviewed": {json.dumps(review_reviewed)}, "not_reviewed": {json.dumps(review_not_reviewed)}}};

    const totalReviewedMarks = reviewData.reviewed.reduce((a, b) => a + b, 0);
    const totalPossibleMarks = reviewData.labels.length * {iaa_metrics['total_records']};
    const overallReviewCompletion = totalPossibleMarks > 0 ? (totalReviewedMarks / totalPossibleMarks) * 100 : 0;
    document.getElementById('overallReviewProgressText').textContent = `${{overallReviewCompletion.toFixed(1)}}% (${{totalReviewedMarks}}/${{totalPossibleMarks}})`;
    document.getElementById('overallReviewProgressFill').style.width = `${{overallReviewCompletion.toFixed(1)}}%`;

    const ctx1 = document.getElementById('overallQwkChart').getContext('2d');
    new Chart(ctx1, {{
      type: 'bar',
      data: {{
        labels: overallData.labels,
        datasets: [{{
          label: 'QWK',
          data: overallData.values,
          backgroundColor: ['#1f77b4', '#2ca02c', '#ff7f0e', '#9467bd'],
          borderRadius: 6
        }}]
      }},
      options: {{
        plugins: {{ legend: {{ display: false }} }},
        scales: {{
          y: {{ min: -0.1, max: 1, ticks: {{ stepSize: 0.2 }} }}
        }}
      }}
    }});

    const ctx2 = document.getElementById('reviewCoverageChart').getContext('2d');
    new Chart(ctx2, {{
      type: 'bar',
      data: {{
        labels: reviewData.labels,
        datasets: [
          {{ label: 'Reviewed (v)', data: reviewData.reviewed, backgroundColor: '#0b6e4f', borderRadius: 6 }},
          {{ label: 'Not reviewed', data: reviewData.not_reviewed, backgroundColor: '#d1d5db', borderRadius: 6 }},
        ]
      }},
      options: {{
        responsive: true,
        scales: {{ x: {{ stacked: true }}, y: {{ stacked: true }} }},
        plugins: {{ legend: {{ position: 'bottom' }} }}
      }}
    }});
  </script>
</body>
</html>
"""

    return html


def main(json_filepath: str, output_filepath: str):
    """Main function to generate report."""
    print(f"Loading JSON from {json_filepath}...")
    data = load_json(json_filepath)
    print(f"Loaded {len(data)} records")

    print("Extracting annotations...")
    records = extract_annotations(data)
    print(f"Extracted annotations for {len(records)} unique records")

    print("Calculating IAA metrics...")
    iaa_metrics = calculate_iaa_metrics(records)

    print("Finding top disagreement records...")
    top_disagreements = find_top_disagreement_records(records, iaa_metrics)

    print("Generating HTML report...")
    html = generate_html(iaa_metrics, top_disagreements)

    print(f"Writing HTML to {output_filepath}...")
    with open(output_filepath, 'w', encoding='utf-8') as f:
        f.write(html)

    print(f"\n✓ Report generated successfully!")
    print(f"  Total records: {iaa_metrics['total_records']}")
    print(f"  Disagreement rate: {iaa_metrics['disagreement_rate']}%")
    print(f"  Annotators: {', '.join(iaa_metrics['annotator_names'])}")
    print(f"  Overall QWK: {iaa_metrics['overall_qwk']}")


if __name__ == '__main__':
