        level = task_data.get('level', '')
        record_id = task_data.get('record_id', '')

        for annotation in task.get('annotations', []):
            annotator_email = annotation.get('completed_by', {}).get('email', 'Unknown')
            annotator_id = annotation.get('completed_by', {}).get('id')

            scores = {}
            is_reviewed = False

            for result in annotation.get('result', []):
                from_name = result.get('from_name', '')
